const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const delhi = ee.Geometry.Polygon(
      [[[76.84074812301982, 28.910041837119156],
        [76.84074812301982, 28.32657731998463],
        [77.47353620895732, 28.32657731998463],
        [77.47353620895732, 28.910041837119156],
        [76.84074812301982, 28.910041837119156]]]);

    const targetDate = ee.Date('2024-01-15');
    const endDate = targetDate.advance(1, 'day'); // Filter for a single day

    // 2. Data Acquisition
    // Using Sentinel-2 Level-2A for Scene Classification Layer (SCL)
    let collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(delhi)
      .filterDate(targetDate, endDate)
      .filter('CLOUD_PIXEL_PERCENTAGE < 99'); // Pre-filter to exclude completely cloudy scenes as a first pass, though we want to check for clouds

    const collectionSize = await collection.size().getInfo();
    console.log(`Sentinel-2 images on 2024-01-15: ${collectionSize}`);

    if (collectionSize === 0) {
      console.log("No Sentinel-2 images found for 2024-01-15.");
      // Fallback to Landsat 9
      console.log("Attempting Landsat 9 fallback...");
      collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_SR')
        .filterBounds(delhi)
        .filterDate(targetDate, endDate);

      const landsatSize = await collection.size().getInfo();
      console.log(`Landsat 9 images on 2024-01-15: ${landsatSize}`);

      if (landsatSize === 0) {
        console.log("No satellite images found for the specified date.");
        console.log("C1");
        return;
      }
    }

    // Select the least cloudy image if multiple exist
    let image = collection.sort('CLOUD_PIXEL_PERCENTAGE').first();
    if (image === null) { // This can happen if sort() returns null despite size > 0 due to no 'CLOUD_PIXEL_PERCENTAGE'
        image = collection.first();
    }

    if (image === null) {
        console.log("No valid image after initial filtering and selection.");
        console.log("C1");
        return;
    }

    const satelliteId = await image.get('SPACECRAFT_ID').getInfo() || await image.get('SATELLITE_ID').getInfo();
    const acquisitionTime = await image.get('system:time_start').getInfo();
    console.log(`Using image from ${satelliteId} acquired on ${new Date(acquisitionTime).toISOString()}`);


    // 3. Processing: Calculate cloud coverage
    let cloudMask;
    let totalAreaReducer;
    let cloudAreaReducer;
    let scale;

    if (satelliteId && satelliteId.startsWith('S2')) { // Sentinel-2
      const scl = image.select('SCL');
      // SCL values for clouds: 8 (medium probability cloud), 9 (high probability cloud)
      cloudMask = scl.eq(8).or(scl.eq(9));
      scale = 20; // Sentinel-2 SCL is 20m resolution
    } else if (satelliteId && satelliteId.startsWith('LANDSAT_9')) { // Landsat 9
      const qaPixel = image.select('QA_PIXEL');
      // Bits 3 and 5 are cloud and cloud shadow, respectively, in Landsat 8/9 QA_PIXEL
      // Bit 3: cloud (1 = cloud, 0 = no cloud)
      // Bit 5: cloud shadow (1 = cloud shadow, 0 = no cloud shadow)
      const cloudBit = 1 << 3; // Bit 3
      const cloudShadowBit = 1 << 5; // Bit 5
      cloudMask = qaPixel.bitwiseAnd(cloudBit).or(qaPixel.bitwiseAnd(cloudShadowBit)).neq(0);
      scale = 30; // Landsat is 30m resolution
    } else {
      console.log("Unsupported satellite type or missing SCL/QA_PIXEL band for cloud detection.");
      console.log("D"); // Incorrect method or missing band
      return;
    }

    // Calculate total pixels within geometry
    const totalPixelsImage = ee.Image.constant(1).updateMask(cloudMask.not()); // Mask out clouds to count non-cloudy, will adjust
    const totalPixelsCount = await totalPixelsImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: delhi,
      scale: scale,
      maxPixels: 1e9
    }).get('constant').getInfo();

    // Calculate cloud pixels within geometry
    const cloudPixelsImage = ee.Image.constant(1).updateMask(cloudMask);
    const cloudPixelsCount = await cloudPixelsImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: delhi,
      scale: scale,
      maxPixels: 1e9
    }).get('constant').getInfo();

    // Sum of both to get actual total valid pixels
    const actualTotalPixelsCount = cloudPixelsCount + totalPixelsCount;

    console.log(`Total valid pixels in Delhi area (scale=${scale}m): ${actualTotalPixelsCount}`);
    console.log(`Cloudy pixels: ${cloudPixelsCount}`);

    if (actualTotalPixelsCount === 0) {
      console.log("No valid pixels in the region after processing.");
      console.log("C2");
      return;
    }

    const cloudCoverage = (cloudPixelsCount / actualTotalPixelsCount) * 100;
    console.log(`Calculated cloud coverage: ${cloudCoverage.toFixed(2)}%`);

    // 4. Validation & Final Answer
    const completeCoverageThreshold = 95; // Define 'complete' as >95% cloud coverage

    if (cloudCoverage === null || isNaN(cloudCoverage)) {
      console.log("C3"); // Calculation failure
    } else if (cloudCoverage >= completeCoverageThreshold) {
      console.log("A"); // Yes, complete cloud coverage
    } else {
      console.log("B"); // No, not complete cloud coverage
    }

  } catch (error) {
    console.error("An error occurred during analysis:", error);
    console.log("D"); // General error, likely due to method or access issues
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
